package vn.biz04;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.*;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.context.annotation.*;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import vn.biz04.data.Store;
import vn.biz04.domain.*;
import vn.biz04.service.*;
import java.math.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.hamcrest.Matchers.*;
@SpringBootTest
@AutoConfigureMockMvc
@ActiveProfiles("test")
@Import(BusinessFlowTest.ClockConfig.class)
@Transactional
class BusinessFlowTest {
    static class TestClock extends Clock { private final AtomicReference<Instant> value=new AtomicReference<>(Instant.parse("2026-10-27T00:00:00Z"));public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return value.get();}void reset(){value.set(Instant.parse("2026-10-27T00:00:00Z"));}void days(int n){value.set(value.get().plus(Duration.ofDays(n)));}}
    @TestConfiguration static class ClockConfig {@Bean @Primary TestClock testClock(){return new TestClock();}}
    @Autowired ProposalService proposalDecisions;
    @Autowired TestServices testServices;@Autowired Store db;@Autowired AccountService accounts;@Autowired CatalogService catalog;@Autowired ContractService contracts;@Autowired PaymentService payments;@Autowired DeliveryService delivery;@Autowired ReviewService reviews;@Autowired DisputeService disputes;@Autowired TerminationService term;@Autowired MockMvc mvc;@Autowired TestClock clock;
    NguoiDung kh,cg,admin,other;static final String PASSWORD="Demo@12345";
    @BeforeEach void before(){clock.reset();String x=UUID.randomUUID().toString();kh=TestAccounts.create(db,"Khách hàng kiểm thử","kh"+x+"@test.local",PASSWORD,true,true);cg=TestAccounts.create(db,"Chuyên gia kiểm thử","cg"+x+"@test.local",PASSWORD,false,true);admin=TestAccounts.create(db,"Quản trị viên kiểm thử","ad"+x+"@test.local",PASSWORD,true,false);admin.setLaQuanTriVien(true);other=TestAccounts.create(db,"Người ngoài","ng"+x+"@test.local",PASSWORD,true,true);}
    record Flow(HopDong h,List<MocNghiemThu> ms){}
    Flow draft(long... amounts){BigDecimal total=Arrays.stream(amounts).mapToObj(BigDecimal::valueOf).reduce(BigDecimal.ZERO,BigDecimal::add);YeuCau y=catalog.request(kh.getMaNguoiDung(),null,"Yêu cầu kiểm thử đầy đủ","Công việc có tiêu chí rõ ràng và sản phẩm bàn giao.",total,null);DeXuat d=catalog.proposal(cg.getMaNguoiDung(),y.getMaYeuCau(),"Phương án thực hiện đúng yêu cầu đã thống nhất.",total,30);proposalDecisions.accept(kh.getMaNguoiDung(),d.getMaDeXuat());HopDong h=TestContracts.legacy(db,d.getMaDeXuat());List<MocNghiemThu> ms=new ArrayList<>();for(int i=0;i<amounts.length;i++)ms.add(contracts.milestone(kh.getMaNguoiDung(),h.getMaHopDong(),null,i+1,"Mốc số "+(i+1),"Sản phẩm theo kế hoạch đã thống nhất","Sản phẩm đạt tiêu chí đã được mô tả",BigDecimal.valueOf(amounts[i]),LocalDate.of(2026,12,1)));return new Flow(h,ms);}
    Flow active(long... amounts){Flow f=draft(amounts);int v=f.h.getPhienBan();contracts.confirm(kh.getMaNguoiDung(),f.h.getMaHopDong(),v);contracts.confirm(cg.getMaNguoiDung(),f.h.getMaHopDong(),v);return f;}
    void fund(MocNghiemThu m){payments.fund(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"SUCCESS");}
    void deliver(MocNghiemThu m){delivery.deliver(cg.getMaNguoiDung(),m.getMaMocNghiemThu(),"Sản phẩm bàn giao đủ nội dung kiểm thử","https://example.com/san-pham");}
    void finish(MocNghiemThu m){fund(m);deliver(m);delivery.accept(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"SUCCESS");}
    @Test void accountPasswordIsHashedAndAdminCannotBeRegistered(){assertNotEquals(PASSWORD,kh.getMatKhauBam());assertTrue(kh.getMatKhauBam().startsWith("$2"));assertFalse(kh.getLaQuanTriVien());}
    @Test void selfProposalRejected(){YeuCau y=catalog.request(kh.getMaNguoiDung(),null,"Yêu cầu của chính mình","Nội dung kiểm tra gửi đề xuất cho chính mình.",BigDecimal.TEN,null);assertThrows(BusinessException.class,()->catalog.proposal(kh.getMaNguoiDung(),y.getMaYeuCau(),"Một phương án không hợp lệ",BigDecimal.TEN,3));}
    @Test void catalogFlowKeepsServiceRequestProposal(){DichVu d=testServices.create(cg.getMaNguoiDung(),null,"Thiết kế nhận diện","Thiết kế","Mô tả dịch vụ theo yêu cầu.",BigDecimal.valueOf(100));YeuCau y=catalog.request(kh.getMaNguoiDung(),d.getMaDichVu(),"Yêu cầu dịch vụ có sẵn","Cần sản phẩm đúng mô tả của dịch vụ.",BigDecimal.valueOf(100),null);assertEquals(d.getMaDichVu(),y.getMaDichVu());assertThrows(BusinessException.class,()->catalog.proposal(other.getMaNguoiDung(),y.getMaYeuCau(),"Chuyên gia không phải chủ dịch vụ",BigDecimal.valueOf(100),5));assertNotNull(catalog.proposal(cg.getMaNguoiDung(),y.getMaYeuCau(),"Phương án của chủ dịch vụ",BigDecimal.valueOf(100),5));}
    @Test void confirmationMustUseCurrentVersion(){Flow f=draft(200);int v=f.h.getPhienBan();contracts.confirm(kh.getMaNguoiDung(),f.h.getMaHopDong(),v);contracts.terms(kh.getMaNguoiDung(),f.h.getMaHopDong(),"Thay đổi nội dung thỏa thuận cho phiên bản mới",BigDecimal.valueOf(200));assertNull(f.h.getPhienBanKhachXacNhan());assertThrows(BusinessException.class,()->contracts.confirm(cg.getMaNguoiDung(),f.h.getMaHopDong(),v));assertEquals("CHO_XAC_NHAN",f.h.getTrangThai());}
    @Test void milestoneSumMustMatch(){Flow f=draft(200);contracts.terms(kh.getMaNguoiDung(),f.h.getMaHopDong(),"Nội dung thỏa thuận cần giữ nhất quán",BigDecimal.valueOf(300));assertThrows(BusinessException.class,()->contracts.confirm(kh.getMaNguoiDung(),f.h.getMaHopDong(),f.h.getPhienBan()));}
    @Test void oneRequestCannotCreateTwoContracts(){Flow f=draft(200);assertEquals(f.h.getMaHopDong(),contracts.select(kh.getMaNguoiDung(),f.h.getMaDeXuat()).getMaHopDong());}
    @Test void fundingMustBeSequential(){Flow f=active(200,300);assertThrows(BusinessException.class,()->fund(f.ms.get(1)));fund(f.ms.get(0));assertThrows(BusinessException.class,()->fund(f.ms.get(1)));}
    @Test void failedFundingCanRetryWithoutDuplicateMoney(){Flow f=active(200);Long id=f.ms.get(0).getMaMocNghiemThu();payments.fund(kh.getMaNguoiDung(),id,"FAIL");assertEquals("CHO_KY_QUY",f.ms.get(0).getTrangThai());assertEquals(0,payments.balance(id).dangGiu().signum());payments.fund(kh.getMaNguoiDung(),id,"SUCCESS");payments.fund(kh.getMaNguoiDung(),id,"SUCCESS");assertEquals(0,BigDecimal.valueOf(200).compareTo(payments.balance(id).dangGiu()));assertEquals(1,db.count("select count(g) from GiaoDich g where g.maMocNghiemThu=:m","m",id));}
    @Test void onlyAllSettledCompletesContract(){Flow f=active(200,300);finish(f.ms.get(0));assertEquals("DANG_THUC_HIEN",f.h.getTrangThai());finish(f.ms.get(1));assertEquals("HOAN_THANH",f.h.getTrangThai());assertNotNull(f.h.getNgayKetThuc());}
    @Test void failedDisbursementDoesNotSettle(){Flow f=active(200);MocNghiemThu m=f.ms.get(0);fund(m);deliver(m);assertFalse(delivery.accept(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"FAIL"));assertEquals("DA_NGHIEM_THU",m.getTrangThai());assertEquals("DANG_THUC_HIEN",f.h.getTrangThai());assertTrue(payments.release(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"SUCCESS"));assertTrue(payments.release(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"SUCCESS"));assertEquals(0,BigDecimal.valueOf(20).compareTo(payments.balance(m.getMaMocNghiemThu()).phi()));}
    @Test void revisionsStoreVersionsAndRestartDeadline(){Flow f=active(200);MocNghiemThu m=f.ms.get(0);fund(m);deliver(m);LocalDateTime old=m.getHanNghiemThu();clock.days(2);delivery.revise(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"Điều chỉnh lại nội dung cần sửa");assertNull(m.getHanNghiemThu());delivery.autoAccept(m.getMaMocNghiemThu());assertEquals("YEU_CAU_CHINH_SUA",m.getTrangThai());deliver(m);assertEquals(old.plusDays(2),m.getHanNghiemThu());assertEquals(2,db.count("select count(b) from BanGiao b where b.maMocNghiemThu=:m","m",m.getMaMocNghiemThu()));}
    @Test void automaticAcceptanceAtDeadline(){Flow f=active(200);MocNghiemThu m=f.ms.get(0);fund(m);deliver(m);clock.days(14);delivery.autoAccept(m.getMaMocNghiemThu());assertEquals("DA_TAT_TOAN",m.getTrangThai());}
    @Test void disputeBlocksAutomaticAcceptance(){Flow f=active(200);MocNghiemThu m=f.ms.get(0);fund(m);deliver(m);disputes.open(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"Không đồng ý với sản phẩm bàn giao");clock.days(15);delivery.autoAccept(m.getMaMocNghiemThu());assertEquals("DANG_TRANH_CHAP",m.getTrangThai());assertEquals(0,BigDecimal.valueOf(200).compareTo(payments.balance(m.getMaMocNghiemThu()).dangGiu()));}
    @Test void duplicateOpenDisputeRejected(){Flow f=active(200);MocNghiemThu m=f.ms.get(0);fund(m);disputes.open(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"Mở hồ sơ tranh chấp hợp lệ");assertThrows(BusinessException.class,()->disputes.open(cg.getMaNguoiDung(),m.getMaMocNghiemThu(),"Mở hồ sơ thứ hai cùng một mốc"));}
    @Test void partialSettlementRetriesOnlyUnpaidLeg(){Flow f=active(2000000);MocNghiemThu m=f.ms.get(0);fund(m);TranhChap t=disputes.open(kh.getMaNguoiDung(),m.getMaMocNghiemThu(),"Hai bên không thống nhất công việc");assertFalse(disputes.decide(admin.getMaNguoiDung(),t.getMaTranhChap(),"Chia tiền dựa trên hồ sơ bằng chứng",BigDecimal.valueOf(800000),false,"FAIL_REFUND"));assertNull(t.getNgayDong());assertEquals(0,BigDecimal.valueOf(1200000).compareTo(payments.balance(m.getMaMocNghiemThu()).dangGiu()));assertTrue(disputes.decide(admin.getMaNguoiDung(),t.getMaTranhChap(),"",BigDecimal.ZERO,false,"SUCCESS"));assertNotNull(t.getNgayDong());PaymentService.Balance b=payments.balance(m.getMaMocNghiemThu());assertEquals(0,BigDecimal.valueOf(720000).compareTo(b.thucNhan()));assertEquals(0,BigDecimal.valueOf(1200000).compareTo(b.hoanKhach()));assertEquals(0,BigDecimal.valueOf(80000).compareTo(b.phi()));assertEquals(0,b.dangGiu().signum());}
    @Test void allocationCannotExceedHeldMoney(){Flow f=active(200);fund(f.ms.get(0));TranhChap t=disputes.open(kh.getMaNguoiDung(),f.ms.get(0).getMaMocNghiemThu(),"Cần giải quyết bất đồng của mốc");assertThrows(BusinessException.class,()->disputes.decide(admin.getMaNguoiDung(),t.getMaTranhChap(),"Kết luận có số tiền không hợp lệ",BigDecimal.valueOf(201),false,"SUCCESS"));}
    @Test void resumeRequiresBothConfirmations(){Flow f=active(200,300);fund(f.ms.get(0));TranhChap t=disputes.open(kh.getMaNguoiDung(),f.ms.get(0).getMaMocNghiemThu(),"Cần xử lý phần công việc hiện tại");disputes.decide(admin.getMaNguoiDung(),t.getMaTranhChap(),"Hoàn tiền mốc này và cho hai bên xác nhận tiếp tục",BigDecimal.ZERO,true,"SUCCESS");assertEquals("CHO_TIEP_TUC",f.h.getTrangThai());assertThrows(BusinessException.class,()->fund(f.ms.get(1)));int v=f.h.getPhienBan();contracts.confirm(kh.getMaNguoiDung(),f.h.getMaHopDong(),v);assertEquals("CHO_TIEP_TUC",f.h.getTrangThai());contracts.confirm(cg.getMaNguoiDung(),f.h.getMaHopDong(),v);fund(f.ms.get(1));}
    @Test void bothReviewsPublishTogether(){Flow f=active(200);finish(f.ms.get(0));reviews.submit(kh.getMaNguoiDung(),f.h.getMaHopDong(),5,"Nội dung khách hàng chưa được lộ");assertTrue(reviews.publicReviews(f.h.getMaHopDong()).isEmpty());reviews.submit(cg.getMaNguoiDung(),f.h.getMaHopDong(),4,"Nội dung chuyên gia hợp lệ");assertEquals(2,reviews.publicReviews(f.h.getMaHopDong()).size());}
    @Test void oneReviewPublishesAtExpiryAndNoMoreSubmission(){Flow f=active(200);finish(f.ms.get(0));reviews.submit(kh.getMaNguoiDung(),f.h.getMaHopDong(),5,"Nhận xét hợp lệ trong thời hạn");clock.days(14);reviews.publish(f.h.getMaHopDong());assertEquals(1,reviews.publicReviews(f.h.getMaHopDong()).size());assertThrows(BusinessException.class,()->reviews.submit(cg.getMaNguoiDung(),f.h.getMaHopDong(),4,"Đánh giá gửi sau thời hạn"));}
    @Test void noDefaultRatingAndViolationStaysHidden(){Flow f=active(200);finish(f.ms.get(0));clock.days(14);reviews.publish(f.h.getMaHopDong());assertTrue(reviews.publicReviews(f.h.getMaHopDong()).isEmpty());clock.reset();reviews.submit(kh.getMaNguoiDung(),f.h.getMaHopDong(),1,"Nội dung cần kiểm duyệt");DanhGia d=db.first("from DanhGia d where d.maHopDong=:h",DanhGia.class,"h",f.h.getMaHopDong()).orElseThrow();reviews.hide(admin.getMaNguoiDung(),d.getMaDanhGia(),"Vi phạm quy tắc nội dung");clock.days(14);reviews.publish(f.h.getMaHopDong());assertTrue(reviews.publicReviews(f.h.getMaHopDong()).isEmpty());}
    @Test void outsidersAndDuplicateReviewsRejected(){Flow f=active(200);finish(f.ms.get(0));assertThrows(BusinessException.class,()->reviews.submit(other.getMaNguoiDung(),f.h.getMaHopDong(),5,"Người ngoài không được gửi"));reviews.submit(kh.getMaNguoiDung(),f.h.getMaHopDong(),5,"Lần đánh giá hợp lệ đầu tiên");assertThrows(BusinessException.class,()->reviews.submit(kh.getMaNguoiDung(),f.h.getMaHopDong(),4,"Không được đánh giá lần hai"));}
    @Test void cancellationWithoutDeliveryHasNoReview(){Flow f=draft(200);contracts.cancel(kh.getMaNguoiDung(),f.h.getMaHopDong());assertFalse(reviews.eligible(f.h));assertThrows(BusinessException.class,()->reviews.submit(kh.getMaNguoiDung(),f.h.getMaHopDong(),5,"Không có sản phẩm bàn giao"));}
    @Test void terminationExampleConservesSixMillion(){Flow f=active(2000000,2000000,2000000,2000000,2000000);finish(f.ms.get(0));finish(f.ms.get(1));fund(f.ms.get(2));YeuCauChamDut y=term.propose(kh.getMaNguoiDung(),f.h.getMaHopDong(),"Hai bên kết thúc công việc giữa chừng",40);assertEquals(0,BigDecimal.valueOf(800000).compareTo(y.getTienChuyenGia()));assertTrue(term.respond(cg.getMaNguoiDung(),y.getMaYeuCauChamDut(),true,"SUCCESS"));BigDecimal net=BigDecimal.ZERO,fee=BigDecimal.ZERO,refund=BigDecimal.ZERO;for(MocNghiemThu m:f.ms){PaymentService.Balance b=payments.balance(m.getMaMocNghiemThu());net=net.add(b.thucNhan());fee=fee.add(b.phi());refund=refund.add(b.hoanKhach());}assertEquals(0,BigDecimal.valueOf(4320000).compareTo(net));assertEquals(0,BigDecimal.valueOf(480000).compareTo(fee));assertEquals(0,BigDecimal.valueOf(1200000).compareTo(refund));assertEquals("DA_HUY",f.ms.get(3).getTrangThai());assertEquals("DA_CHAM_DUT",f.h.getTrangThai());}
    @Test void oneSidedTerminationDoesNotRefundAndRejectOpensDispute(){Flow f=active(200);fund(f.ms.get(0));YeuCauChamDut y=term.propose(kh.getMaNguoiDung(),f.h.getMaHopDong(),"Khách hàng đề nghị ngừng thực hiện",0);clock.days(4);assertEquals(0,BigDecimal.valueOf(200).compareTo(payments.balance(f.ms.get(0).getMaMocNghiemThu()).dangGiu()));assertFalse(term.respond(cg.getMaNguoiDung(),y.getMaYeuCauChamDut(),false,"SUCCESS"));assertEquals("TAM_DUNG",f.h.getTrangThai());assertEquals("CHO_GIAI_QUYET",y.getTrangThai());}
    @Test void csrfAndObjectPermissionsAreEnforced()throws Exception{Flow f=active(200);mvc.perform(post("/hop-dong/"+f.h.getMaHopDong()+"/huy").with(user(kh.getEmail()))).andExpect(status().isForbidden());mvc.perform(get("/hop-dong/"+f.h.getMaHopDong()).with(user(other.getEmail()))).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/bang-dieu-khien"));mvc.perform(get("/quan-tri").with(user(other.getEmail()))).andExpect(status().is3xxRedirection());}
    @Test void renderedContractDoesNotLeakHiddenReview()throws Exception{Flow f=active(200);finish(f.ms.get(0));reviews.submit(kh.getMaNguoiDung(),f.h.getMaHopDong(),1,"SECRET_REVIEW_BEFORE_REVEAL");mvc.perform(get("/hop-dong/"+f.h.getMaHopDong()).with(user(cg.getEmail()))).andExpect(status().isOk()).andExpect(content().string(not(containsString("SECRET_REVIEW_BEFORE_REVEAL"))));}
    @Test void mainPagesRender()throws Exception{testServices.create(cg.getMaNguoiDung(),null,"Dịch vụ kiểm thử trang","Thiết kế","Mô tả đủ dài để kiểm tra trang",BigDecimal.TEN);Flow f=active(200);fund(f.ms.get(0));deliver(f.ms.get(0));TranhChap t=disputes.open(kh.getMaNguoiDung(),f.ms.get(0).getMaMocNghiemThu(),"Kiểm tra hiển thị trang tranh chấp");for(String url:List.of("/","/dang-nhap","/dang-ky","/trang/trangchu"))mvc.perform(get(url)).andExpect(status().isOk());for(String url:List.of("/chuyen-gia/"+cg.getMaNguoiDung(),"/bang-dieu-khien","/ho-so","/yeu-cau","/yeu-cau/moi","/dich-vu/soan","/yeu-cau/"+f.h.getMaYeuCau(),"/hop-dong/"+f.h.getMaHopDong(),"/tranh-chap/"+t.getMaTranhChap()))mvc.perform(get(url).with(user(kh.getEmail()))).andExpect(status().isOk());mvc.perform(get("/quan-tri").with(user(admin.getEmail()))).andExpect(status().isOk());}
    @Test void dateFromHtmlFormIsAccepted()throws Exception{mvc.perform(post("/yeu-cau").with(user(kh.getEmail())).with(csrf()).param("tieuDe","Yêu cầu có ngày từ biểu mẫu").param("moTa","Nội dung đủ dài cho yêu cầu kiểm thử ngày.").param("nganSach","100").param("han","2026-12-15")).andExpect(status().is3xxRedirection());assertTrue(db.count("select count(y) from YeuCau y where y.maKhachHang=:u and y.hanDuKien is not null","u",kh.getMaNguoiDung())>0);}

}
